CREATE POLICY rigor_avatar_read ON storage.objects FOR SELECT TO authenticated USING(bucket_id='rigor-avatars' AND (storage.foldername(name))[1]=auth.uid()::text); CREATE POLICY rigor_avatar_insert ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='rigor-avatars' AND (storage.foldername(name))[1]=auth.uid()::text); CREATE POLICY rigor_avatar_update ON storage.objects FOR UPDATE TO authenticated USING(bucket_id='rigor-avatars' AND (storage.foldername(name))[1]=auth.uid()::text) WITH CHECK(bucket_id='rigor-avatars' AND (storage.foldername(name))[1]=auth.uid()::text); CREATE POLICY rigor_avatar_delete ON storage.objects FOR DELETE TO authenticated USING(bucket_id='rigor-avatars' AND (storage.foldername(name))[1]=auth.uid()::text);